"""Prepare self-contained Kusto checks using the public collection-conversion API.

Run from the repository root with PYTHONPATH=. python tests/fixtures/correlation/generate.py.
The expected rows below are worked examples, independent of the generated query.
"""

from pathlib import Path

import yaml

from sigma.backends.kusto import KustoBackend
from sigma.collection import SigmaCollection
from sigma.processing.pipeline import ProcessingPipeline

DESTINATION = Path(__file__).parent


def query(*, operator="gte", threshold=2, groups=(), duplicate_sources=False):
    source = {
        "title": "Fixture source",
        "name": "source-rule",
        "logsource": {"product": "fixture"},
        "detection": {
            "selection": {"Marker": "match"},
            "alternate": {"Marker": "match"},
            "condition": ["selection", "alternate"] if duplicate_sources else "selection",
        },
    }
    documents = [source]
    references = ["source-rule"]
    if duplicate_sources:
        documents.append({**source, "title": "Other fixture source", "name": "other-rule"})
        references.append("other-rule")
    documents.append(
        {
            "title": "Fixture event count",
            "correlation": {
                "type": "event_count",
                "rules": references,
                "group-by": list(groups),
                "timespan": "5m",
                "condition": {operator: threshold},
            },
        }
    )
    collection = SigmaCollection.from_yaml(yaml.safe_dump_all(documents))
    pipeline = ProcessingPipeline.from_dict(
        {"transformations": [{"type": "set_state", "key": "query_table", "val": "Events"}]}
    )
    (converted,) = KustoBackend(processing_pipeline=pipeline, correlation_timestamp_field="Timestamp").convert(
        collection
    )
    return converted


def check(actual, expected, fields):
    """An empty result means exact multiset equality, including result multiplicity."""
    return (
        f"union ({actual} | extend Delta = 1), ({expected} | extend Delta = -1)\n"
        f"| summarize Delta = sum(Delta) by {', '.join(fields)}\n"
        "| where Delta != 0\n"
    )


HEADER = """// Prepared deterministic fixture; live engine execution has not been performed.
// Generated by tests/fixtures/correlation/generate.py via KustoBackend.convert().
// Run the entire file in one Kusto query. PASS = zero output rows.
// Nonempty rows identify a missing, additional, or duplicated summary.
"""


def grouped_fixture():
    data = """let Events = datatable(Timestamp:string, Case:string, User:dynamic, Marker:string) [
    "2026-01-01T12:00:59Z", "boundary", dynamic("alice"), "match",
    "2026-01-01T12:05:01Z", "boundary", dynamic("alice"), "match",
    "2026-01-01T12:00:00Z", "endpoint", dynamic("alice"), "match",
    "2026-01-01T12:05:00Z", "endpoint", dynamic("alice"), "match",
    "2026-01-01T12:00:00Z", "outside", dynamic("alice"), "match",
    "2026-01-01T12:05:00.0000001Z", "outside", dynamic("alice"), "match",
    "2026-01-01T12:00:00Z", "ties", dynamic("alice"), "match",
    "2026-01-01T12:00:00Z", "ties", dynamic("alice"), "match",
    "2026-01-01T12:01:00Z", "ties", dynamic("alice"), "match",
    "2026-01-01T12:00:00Z", "overlap", dynamic("alice"), "match",
    "2026-01-01T12:01:00Z", "overlap", dynamic("alice"), "match",
    "2026-01-01T12:02:00Z", "overlap", dynamic("alice"), "match",
    "2026-01-01T12:00:00Z", "split", dynamic("alice"), "match",
    "2026-01-01T12:01:00Z", "split", dynamic("bob"), "match",
    "2026-01-01T12:00:00Z", "missing", dynamic("alice"), "match",
    "not a timestamp", "missing", dynamic("alice"), "match",
    "", "missing", dynamic("alice"), "match",
    "2026-01-01T12:01:00Z", "missing", dynamic(""), "match",
    "2026-01-01T12:02:00Z", "missing", dynamic(null), "match",
    "2026-01-01T12:03:00Z", "", dynamic("alice"), "match"
];
"""
    expected = """let Expected = datatable(WindowStart:datetime, WindowEnd:datetime, Case:string, User:string, EventCount:long) [
    datetime(2026-01-01T12:00:01Z), datetime(2026-01-01T12:05:01Z), "boundary", "alice", 2,
    datetime(2026-01-01T12:00:00Z), datetime(2026-01-01T12:05:00Z), "endpoint", "alice", 2,
    datetime(2026-01-01T11:55:00Z), datetime(2026-01-01T12:00:00Z), "ties", "alice", 2,
    datetime(2026-01-01T11:56:00Z), datetime(2026-01-01T12:01:00Z), "ties", "alice", 3,
    datetime(2026-01-01T11:56:00Z), datetime(2026-01-01T12:01:00Z), "overlap", "alice", 2,
    datetime(2026-01-01T11:57:00Z), datetime(2026-01-01T12:02:00Z), "overlap", "alice", 3
];
"""
    return (
        HEADER
        + data
        + "let Actual = () {\n"
        + query(groups=("Case", "User"))
        + "\n};\n"
        + expected
        + check("Actual()", "Expected", ["WindowStart", "WindowEnd", "Case", "User", "EventCount"])
    )


def duplicate_fixture():
    data = """// Each physical input row satisfies two searches in each of two source rules.
let Events = datatable(Timestamp:string, Marker:string) [
    "2026-01-01T12:00:00Z", "match",
    "2026-01-01T12:00:00Z", "match",
    "2026-01-01T12:01:00Z", "match"
];
"""
    expected = """let Expected = datatable(WindowStart:datetime, WindowEnd:datetime, EventCount:long) [
    datetime(2026-01-01T11:55:00Z), datetime(2026-01-01T12:00:00Z), 8,
    datetime(2026-01-01T11:56:00Z), datetime(2026-01-01T12:01:00Z), 12
];
"""
    return (
        HEADER
        + data
        + "let Actual = () {\n"
        + query(duplicate_sources=True)
        + "\n};\n"
        + expected
        + check("Actual()", "Expected", ["WindowStart", "WindowEnd", "EventCount"])
    )


def comparisons_fixture():
    data = """// The only anchors/counts are 12:00=2, 12:05=3, 12:05:00.0000001=2, 12:20=1.
// Expiring events between these times never create evaluations. eq-zero stays empty.
let Events = datatable(Timestamp:string, Marker:string) [
    "2026-01-01T12:00:00Z", "match",
    "2026-01-01T12:00:00Z", "match",
    "2026-01-01T12:05:00Z", "match",
    "2026-01-01T12:05:00.0000001Z", "match",
    "2026-01-01T12:20:00Z", "match",
    "invalid", "match"
];
"""
    scenarios = [("gt", 2), ("gte", 2), ("lt", 2), ("lte", 2), ("eq", 2), ("neq", 2), ("eq", 0)]
    functions = "".join(
        f"let {op}_{threshold} = () {{\n{query(operator=op, threshold=threshold)}\n}};\n" for op, threshold in scenarios
    )
    actual = (
        "let Actual = union\n"
        + ",\n".join(f'    ({op}_{threshold}() | extend Scenario = "{op}_{threshold}")' for op, threshold in scenarios)
        + ";\n"
    )
    expected = """let Expected = datatable(Scenario:string, WindowStart:datetime, WindowEnd:datetime, EventCount:long) [
    "gt_2", datetime(2026-01-01T12:00:00Z), datetime(2026-01-01T12:05:00Z), 3,
    "gte_2", datetime(2026-01-01T11:55:00Z), datetime(2026-01-01T12:00:00Z), 2,
    "gte_2", datetime(2026-01-01T12:00:00Z), datetime(2026-01-01T12:05:00Z), 3,
    "gte_2", datetime(2026-01-01T12:00:00.0000001Z), datetime(2026-01-01T12:05:00.0000001Z), 2,
    "lt_2", datetime(2026-01-01T12:15:00Z), datetime(2026-01-01T12:20:00Z), 1,
    "lte_2", datetime(2026-01-01T11:55:00Z), datetime(2026-01-01T12:00:00Z), 2,
    "lte_2", datetime(2026-01-01T12:00:00.0000001Z), datetime(2026-01-01T12:05:00.0000001Z), 2,
    "lte_2", datetime(2026-01-01T12:15:00Z), datetime(2026-01-01T12:20:00Z), 1,
    "eq_2", datetime(2026-01-01T11:55:00Z), datetime(2026-01-01T12:00:00Z), 2,
    "eq_2", datetime(2026-01-01T12:00:00.0000001Z), datetime(2026-01-01T12:05:00.0000001Z), 2,
    "neq_2", datetime(2026-01-01T12:00:00Z), datetime(2026-01-01T12:05:00Z), 3,
    "neq_2", datetime(2026-01-01T12:15:00Z), datetime(2026-01-01T12:20:00Z), 1
];
"""
    return (
        HEADER
        + data
        + functions
        + actual
        + expected
        + check("Actual", "Expected", ["Scenario", "WindowStart", "WindowEnd", "EventCount"])
    )


def fixtures():
    return {
        "event_count_grouped.kql": grouped_fixture(),
        "event_count_duplicate_sources.kql": duplicate_fixture(),
        "event_count_comparisons.kql": comparisons_fixture(),
    }


if __name__ == "__main__":
    for name, content in fixtures().items():
        (DESTINATION / name).write_text(content)
